Method.Source:
    /// <summary>
    ///  METExcludeForPayment field must be visible only for Rebate Item Groups
    /// </summary>
    /// <param name="sender">Get Table buffer</param>
    /// <param name="e"> Get form data source args</param>
    [FormDataSourceEventHandler(formDataSourceStr(TAMRebateGroupLink, TAMRebateGroupLink), FormDataSourceEventType::Activated)]
    public static void TAMRebateGroupLink_OnActivated(FormDataSource sender, FormDataSourceEventArgs e)
    {
        TAMRebateGroupLink rebateGroupLink;

        rebateGroupLink = sender.cursor();
        if(rebateGroupLink.ModuleInventCustVend == ModuleInventCustVend::Invent)
        {
            sender.object(fieldNum(TAMRebateGroupLink, METExcludeForPayment)).visible(true);
        }
        else
        {
            sender.object(fieldNum(TAMRebateGroupLink, METExcludeForPayment)).visible(false);
        }
    }
